&lt;script&gt;
function sendReminder(userId) {
  if(!confirm(&#039;Are you sure you want to send a reminder email to this employee?&#039;)) return;

  var formData = new FormData();
  formData.append(&#039;user_id&#039;, userId);
  formData.append(&#039;csrf_token&#039;, &#039;28e7299ca71e37718700444f4dcb4a98&#039;);

  var btn = event.currentTarget;
  var originalText = btn.innerHTML;
  btn.innerHTML = &#039;&lt;i class=&quot;feather icon-loader&quot;&gt;&lt;/i&gt; Sending...&#039;;
  btn.disabled = true;

  fetch(&#039;https://integratedsystems.globalmaintenance.co.id/erp/training-record-email&#039;, {
    method: &#039;POST&#039;,
    body: formData
  })
  .then(function(r){ return r.json(); })
  .then(function(data){
    btn.innerHTML = originalText;
    btn.disabled = false;
    if(data.error) {
      toastr.error(data.error);
    } else {
      toastr.success(data.result);
    }
  })
  .catch(function(err){
    btn.innerHTML = originalText;
    btn.disabled = false;
    toastr.error(&#039;Error: &#039; + err);
  });
}
&lt;/script&gt;

